-- Isolated read-projection fixtures only. Parent references are synthetic; no source workflow is executed.
BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Agency current-work projection fixture');
create function pg_temp.evidence(product text)returns jsonb language sql as $$select public.agency_observation_evidence('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',product)$$;
create function pg_temp.review(i uuid,product text,h text)returns jsonb language sql as $$select public.decide_agency_observation(i,'ee720000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('operation','review','product',product,'sourceHash',h,'decision','watch','reason','Review the displayed work summary'))$$;
