select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','siteforge')where id='ee720000-0000-4000-8000-000000000010'),'native source siteforge_incidents included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','forgestudio')where id='ee720000-0000-4000-8000-000000000011'),'native source social_publications included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','reviewflow')where id='ee720000-0000-4000-8000-000000000012'),'native source reviewflow_publications included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','marketvision')where id='ee720000-0000-4000-8000-000000000013'),'native source marketvision_source_requests included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','marketvision')where id='ee720000-0000-4000-8000-000000000014'),'native source marketvision_extraction_requests included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','marketvision')where id='ee720000-0000-4000-8000-000000000015'),'native source marketvision_brand_requests included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','knowledge')where id='ee720000-0000-4000-8000-000000000016'),'native source knowledge_embedding_requests included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','bi')where id='ee720000-0000-4000-8000-000000000017'),'native source bi_schedule_deliveries included');
select pg_temp.check_it(exists(select 1 from public.agency_current_work('ee720000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','crm')where id='ee720000-0000-4000-8000-000000000018'),'native source crm_handoffs included');
select pg_temp.check_it(pg_temp.evidence('marketvision')->>'failedCount'='0'and pg_temp.evidence('marketvision')->'currentWork'->>'total'='3','held work visible without failed action and outside recent window');
select pg_temp.check_it(pg_temp.evidence('reviewflow')->'currentWork'->>'unconfirmedCount'='1','staff uncertain publication is unconfirmed');
select pg_temp.check_it(pg_temp.evidence('siteforge')->'currentWork'->>'incidentCount'='1','open incident is separate from failure count');
select pg_temp.check_it(pg_temp.evidence('crm')->'currentWork'->'items'->0->'changed_at'='null','missing change time is not invented');
select pg_temp.check_it(pg_temp.evidence('reviewflow')::text not like '%synthetic private source%','private source payloads excluded');
select pg_temp.check_it(public.agency_work_summary('ee720000-0000-4000-8000-000000000001',gen_random_uuid(),'marketvision')->>'total'='0','native organization isolation');
select pg_temp.check_it(public.agency_work_summary(gen_random_uuid(),'22222222-2222-2222-2222-222222222222','marketvision')->>'total'='0','native property isolation');
insert into st values('market',pg_temp.evidence('marketvision'));
select pg_temp.check_it(pg_temp.review('ee720000-0000-4000-8000-000000000080','marketvision',(select v->>'sourceHash'from st where k='market'))->>'state'='saved','held-only recommendation can be reviewed');
select pg_temp.check_it(pg_temp.review('ee720000-0000-4000-8000-000000000080','marketvision',(select v->>'sourceHash'from st where k='market'))->>'state'='replayed','held review retains exact retry identity');
select pg_temp.check_it((select evidence->'currentWork'->>'total'='3'from public.agency_observation_reviews where id='ee720000-0000-4000-8000-000000000080'),'review retains displayed source summary');
select pg_temp.check_it((select result->'executionAuthorized'='false'and not training_eligible from public.shared_action_events where id='ee720000-0000-4000-8000-000000000080'),'review cannot execute or grant training');
