update public.marketvision_source_requests set version=version+1 where id='ee720000-0000-4000-8000-000000000013';
SET LOCAL session_replication_role=origin;
select pg_temp.check_it(pg_temp.review(gen_random_uuid(),'marketvision',(select v->>'sourceHash'from st where k='market'))->>'state'='evidence_changed','same-status source revision invalidates old summary');
select pg_temp.check_it(pg_temp.review('ee720000-0000-4000-8000-000000000080','marketvision',(select v->>'sourceHash'from st where k='market'))->>'state'='replayed','committed receipt survives source changes');
