update public.reviewflow_publications set state='awaiting_confirmation'where id='ee720000-0000-4000-8000-000000000012';
update public.bi_schedule_deliveries set closed=true where id='ee720000-0000-4000-8000-000000000017';
SET LOCAL session_replication_role=origin;
select pg_temp.check_it(pg_temp.evidence('reviewflow')->'currentWork'->>'heldCount'='1'and pg_temp.evidence('reviewflow')->'currentWork'->>'unconfirmedCount'='0','prepared manual publication is waiting for review, not proof of a send');
select pg_temp.check_it(pg_temp.evidence('bi')->'currentWork'->>'total'='0','closed unknown delivery is not unfinished');
SET LOCAL session_replication_role=replica;
update public.siteforge_incidents set status='resolved'where id='ee720000-0000-4000-8000-000000000010';
update public.social_publications set status='published'where id='ee720000-0000-4000-8000-000000000011';
update public.reviewflow_publications set state='reported'where id='ee720000-0000-4000-8000-000000000012';
update public.marketvision_source_requests set state='received'where id='ee720000-0000-4000-8000-000000000013';
update public.marketvision_extraction_requests set state='stopped'where id='ee720000-0000-4000-8000-000000000014';
update public.marketvision_brand_requests set state='stopped'where id='ee720000-0000-4000-8000-000000000015';
update public.knowledge_embedding_requests set state='ready'where id='ee720000-0000-4000-8000-000000000016';
update public.bi_schedule_deliveries set state='accepted'where id='ee720000-0000-4000-8000-000000000017';
update public.crm_handoffs set state='confirmed'where id='ee720000-0000-4000-8000-000000000018';
SET LOCAL session_replication_role=origin;
select pg_temp.check_it(pg_temp.evidence('bi')->'currentWork'->>'total'='0','resolved bi work leaves current queue');
select pg_temp.check_it(pg_temp.evidence('crm')->'currentWork'->>'total'='0','resolved crm work leaves current queue');
select pg_temp.check_it(pg_temp.evidence('forgestudio')->'currentWork'->>'total'='0','resolved forgestudio work leaves current queue');
select pg_temp.check_it(pg_temp.evidence('knowledge')->'currentWork'->>'total'='0','resolved knowledge work leaves current queue');
select pg_temp.check_it(pg_temp.evidence('marketvision')->'currentWork'->>'total'='0','resolved marketvision work leaves current queue');
select pg_temp.check_it(pg_temp.evidence('reviewflow')->'currentWork'->>'total'='0','resolved reviewflow work leaves current queue');
select pg_temp.check_it(pg_temp.evidence('siteforge')->'currentWork'->>'total'='0','resolved siteforge work leaves current queue');
select pg_temp.check_it((select evidence->'currentWork'->>'total'='3'from public.agency_observation_reviews where id='ee720000-0000-4000-8000-000000000080'),'historical reviewed summary is immutable after resolution');
select pg_temp.check_it(not has_function_privilege('authenticated','public.agency_current_work(uuid,uuid,text)','EXECUTE')and not has_function_privilege('anon','public.agency_work_summary(uuid,uuid,text)','EXECUTE'),'projections remain service-only');
select 'Current work assertions: '||n from assertion_count;
ROLLBACK;
